const $=s=>document.querySelector(s);let user,csrf='',state,config={},page='overview',kind='borrow',stream=null,photo=null,photoURL=null,annotatedURL=null,rows=[],source='manual',pending=null,saving=false,receipt=null,rentStart='',rentDue='',rentDueHour='18',plantArea='',selectedReservation=null;
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',stock:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 0v10l9 4 9-4V7M12 11v10"/>',history:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 6"/>',photos:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="11" r="2"/><path d="m14 16-3-3-7 7"/>',reserve:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 11h18"/>',report:'<path d="M4 19V9M10 19V5M16 19v-7M22 19H2"/><path d="m3 7 6-4 6 6 6-5"/>',camera:'<rect x="3" y="6" width="18" height="14" rx="2"/><path d="m8 6 2-3h4l2 3"/><circle cx="12" cy="13" r="4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.stock}</svg>`;
const names={overview:'운영 대시보드',stock:'공구·재고 관리',history:'출납 이력',photos:'이벤트 사진',reserve:'장기 대여 예약',report:'주간 운영 리포트',users:'사용자별 출납 현황',camera:'공구 촬영',review:'인식 결과 확인',complete:'처리 완료'};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=x=>x?new Date(x).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const mode=()=>$('#mode').value;const modeLabel=()=>$('#mode').selectedOptions[0].textContent;
const dayLabel=x=>x?String(x).slice(0,10).replace(/(\d{4})-(\d{2})-(\d{2})/,'$1년 $2월 $3일'):'—';
const hourLabel=h=>h?`${String(h).padStart(2,'0')}시`:'';
const hourOptions=(selected='18')=>Array.from({length:24},(_,i)=>i+1).map(h=>`<option value="${h}" ${Number(selected)===h?'selected':''}>${hourLabel(h)}</option>`).join('');
const periodLabel=(a,b,h)=>`대여 예정일 : ${dayLabel(a)} ~ ${dayLabel(b)}${h?` ${hourLabel(h)}`:''}`;
const todayISO=()=>{const n=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Seoul'}));return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`};
const plantOptions=(selected='')=>((state.plants||['원료','소결','제선','제강','연속주조','열연','냉연','도금(표면처리)','후판','선재']).map(p=>`<option value="${esc(p)}" ${p===selected?'selected':''}>${esc(p)}</option>`).join(''));
const statusLabel={pending:'승인 대기',approved:'가능',rejected:'불가',active:'대여 중',returned:'반납 완료',cancelled:'취소됨'};

function notify(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,6000)}
async function api(path,body,form=false){if(!form&&body&&path==='reservations')body.rent_due_hour=Number(document.querySelector('[name="rent_due_hour"]')?.value||18);if(!form&&body&&path==='events'&&body.kind==='borrow')body.rent_due_hour=Number(rentDueHour);const headers={'X-CSRF-Token':csrf,'X-STBM-Request':'1'};if(!form)headers['Content-Type']='application/json';const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers,...(body?{body:form?body:JSON.stringify(body)}:{})});let d;try{d=await r.json()}catch{throw Error('서버 응답을 확인할 수 없습니다. 기록을 확인한 뒤 다시 시도하세요.')}if(!r.ok){if(r.status===401&&path!=='login')loginView();throw Error(d.error||'요청을 처리하지 못했습니다.')}return d}
function stopCamera(){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null}
function clearPhoto(){stopCamera();photo=null;if(photoURL)URL.revokeObjectURL(photoURL);photoURL=null;annotatedURL=null}
function loginView(){clearPhoto();$('#toast').hidden=true;user=null;csrf='';$('#workspace').hidden=true;$('#login-view').hidden=false;document.body.classList.remove('worker-mode');$('#confirm-dialog').close();$('#detail-dialog').close()}
function setUser(d){$('#toast').hidden=true;user=d;csrf=d.csrf;$('#workspace').hidden=false;$('#login-view').hidden=true;$('#user-name').textContent=d.name;$('#user-role').textContent=d.role==='admin'?'관리자':'현장 작업자';$('#avatar').textContent=d.name[0];document.body.classList.toggle('worker-mode',d.role!=='admin');page='overview';navigation()}
function navigation(){const menu=user.role==='admin'?['overview','stock','history','photos','reserve','report','users']:['overview','history','photos','reserve'];$('#navigation').innerHTML=menu.map(n=>`<a href="#${n}" data-nav="${n}" class="${page===n?'active':''}">${icon(n)}${n==='overview'&&user.role!=='admin'?'내 작업 공간':names[n]}</a>`).join('')}
async function load(){state=await api('state?mode='+mode());config=await api('config')}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">SMART TOOL BOX / ${esc(modeLabel())}</p><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p class="muted">${subtitle}</p></div>${action}</div>${body}</section>`}
function toolsTable(){return `<div class="scroll"><table><thead><tr><th>공구 종류</th><th>전체 보유</th><th>대여 중</th><th>예약</th><th>이상 대기</th><th>대여 가능</th><th>재고 상태</th></tr></thead><tbody>${state.stock.map(s=>`<tr><td><span class="tool-mark">⌁</span><b>${esc(s.tool)}</b></td><td>${s.total}</td><td>${s.borrowed}</td><td>${s.reserved||0}</td><td>${s.damaged||0}</td><td><b>${s.available}</b></td><td><span class="badge ${s.available?'green':'gray'}">${s.available?'대여 가능':'가용 없음'}</span></td></tr>`).join('')}</tbody></table></div>`}
function periodCell(g){const start=g.rent_start,due=g.rent_due;if(start&&due)return `<div class="period-cell"><b>${dayLabel(start)}</b><span>~</span><b>${dayLabel(due)} ${hourLabel(g.rent_due_hour)}</b></div>`;if(g.loan_rent_start&&g.loan_rent_due)return `<div class="period-cell muted"><b>${dayLabel(g.loan_rent_start)}</b><span>~</span><b>${dayLabel(g.loan_rent_due)} ${hourLabel(g.loan_rent_due_hour)}</b><small>연결 대여</small></div>`;return '<span class="muted">—</span>'}
function recordsTable(groups,compact=false){if(!groups.length)return '<div class="empty">아직 출납 기록이 없습니다.</div>';return `<div class="scroll"><table><thead><tr><th>처리 시간</th><th>사용자</th><th>공구 / 수량</th><th>대여 기간</th><th>유형</th><th>사진</th><th>상세</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${time(g.created)}</td><td><b>${esc(g.name)}</b></td><td>${g.plant?`<span class="badge gray">${esc(g.plant)}</span> `:''}${g.items.map(i=>`${esc(i.tool)} <b>${i.qty}</b>`).join(' · ')}</td><td>${periodCell(g)}</td><td><span class="badge ${g.kind==='return'?'green':''}">${g.kind==='return'?'반납':'대여'}</span></td><td>${g.has_photo?'<span class="badge green">있음</span>':'<span class="badge gray">없음</span>'}</td><td><button class="quiet" data-detail="${g.id}" aria-label="기록 ${g.id} 상세">#${g.id} ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function adminOverview(){const total=state.stock.reduce((a,s)=>a+s.total,0),borrowed=state.stock.reduce((a,s)=>a+s.borrowed,0),available=state.stock.reduce((a,s)=>a+s.available,0),reserved=state.stock.reduce((a,s)=>a+(s.reserved||0),0);const overdue=state.overdue||[];const banner=overdue.length?`<div class="overdue-banner" role="alert"><div class="overdue-kicker">미반납 알림</div><div class="overdue-title">미반납</div><p>반납 예정일이 하루 이상 지난 작업자가 있습니다.</p>${overdue.map(o=>`<div class="overdue-item"><b>${esc(o.name)}${o.plant?` · ${esc(o.plant)}`:''} · ${periodLabel(o.rent_start,o.rent_due)}</b><span>${Object.entries(o.items).map(([k,v])=>`${esc(k)} ${v}개`).join(' · ')} · ${o.days_overdue}일 연체</span></div>`).join('')}</div>`:'';const rep=state.report||null;const reportPanel=rep?panel('주간 운영 리포트',`${rep.period_start} ~ ${rep.period_end} · 연체율·파손/수리율·인기 공구`,`<div class="report-kpis"><article class="card report-kpi"><span>연체율</span><strong>${Math.round((rep.overdue_rate||0)*100)}%</strong><small>미반납 ${rep.overdue_open}/${rep.open_loans}건</small></article><article class="card report-kpi"><span>파손·수리율</span><strong>${Math.round((rep.damage_rate||0)*100)}%</strong><small>파손 ${rep.damaged_qty} · 수리 ${rep.repair_qty} / 반납 ${rep.return_qty}</small></article><article class="card report-kpi"><span>주간 대여</span><strong>${rep.borrow_qty}</strong><small>반납 ${rep.return_qty}개</small></article></div><div class="report-tools"><h3 style="margin:0 0 10px;font-size:13px">공구별</h3>${(rep.top_tools||[]).length?(rep.top_tools.map(t=>{const max=Math.max(1,...rep.top_tools.map(x=>x.qty));return `<div class="movement"><div class="movement-head"><b>${esc(t.tool)}</b><span class="muted">${t.qty}개 대여</span></div><div class="bar-track"><div class="bar" style="width:${t.qty/max*100}%"></div></div></div>`}).join('')):'<div class="empty">이번 주 대여 기록이 없습니다.</div>'}<h3 style="margin:18px 0 10px;font-size:13px">공정별</h3>${(rep.by_plant||[]).length?(rep.by_plant.map(t=>{const max=Math.max(1,...rep.by_plant.map(x=>x.qty));return `<div class="movement"><div class="movement-head"><b>${esc(t.plant)}</b><span class="muted">${t.qty}개 대여</span></div><div class="bar-track"><div class="bar return" style="width:${t.qty/max*100}%"></div></div></div>`}).join('')):'<div class="empty">공정별 대여 기록이 없습니다.</div>'}</div>`):'';const vals=[['전체 공구 보유',total,'등록된 공구 수량','⌁'],['현재 대여 중',borrowed,'전체 사용자 미반납 수량','↗'],['대여 가능',available,`예약 ${reserved}개 제외 · 지금 사용 가능`,'✓'],['반납 완료 건수',state.return_count,'누적 반납 처리 건수 · 수량 아님','↙']];return heading('운영 현황','공구 출납과 재고를 한눈에 확인하세요.',`<button data-refresh>↻ 새로고침</button><button class="primary" data-start="borrow">+ 공구 출납</button>`)+banner+reportPanel+`<div class="kpis">${vals.map(([t,v,f,i])=>`<article class="card kpi"><div class="kpi-top">${t}<span class="kpi-icon">${i}</span></div><strong>${v}</strong><small>${t.includes('건수')?'건':'개'}</small><div class="kpi-foot">${f}</div></article>`).join('')}</div><div class="dashboard-grid">${panel('공구별 재고 현황','대여 가능 = 전체 − 대여 중 − 예약',toolsTable(),'<a href="#stock" data-nav="stock">재고 관리 ↗</a>')}${panel('공구별 출납 수량','현재 기록 구분의 누적 수량',`<div class="panel-body"><div class="legend"><span><i></i>대여</span><span><i class="green"></i>반납</span></div>${movement()}</div>`)}</div>`+panel('최근 출납 기록','한 번의 처리를 하나의 기록으로 표시합니다.',recordsTable(state.groups.slice(0,5)),`<a href="#history" data-nav="history">전체 보기 →</a>`)+panel('현재 대여 사용자','반납하지 않은 공구를 사용자별로 확인합니다.',`<div class="panel-body">${holderSummary()}</div>`)+panel('공정별 사용 현황','지금 대여 중인 공구가 어느 공정에 나가 있는지 확인합니다.',`<div class="panel-body">${(state.plant_holders||[]).length?(state.plant_holders.map(h=>`<div class="holder-line"><span>${esc(h.plant)}</span><span>${esc(h.tool)} <b>${h.qty}개</b></span></div>`).join('')):'<div class="empty">공정이 지정된 대여가 없습니다.</div>'}</div>`)+panel('공구함 접속 QR','공구 식별이 아닌 웹사이트 접속용 QR입니다.',`<div class="panel-body qr-box"><img src="/api/qr" alt="Smart Tool Box 접속 QR"><div><b>Smart Tool Box 바로가기</b><p class="muted"><code>${esc(config.public_url)}</code></p><p class="muted">${config.public_url?.includes('127.0.0.1')?'현재 컴퓨터 전용 주소입니다. 휴대폰용 HTTPS 주소를 설정한 뒤 QR을 사용하세요.':'접속 가능한 네트워크에서 카메라로 스캔하세요.'}</p><a href="/api/qr" download="SmartToolBox-QR.svg">QR 다운로드 ↓</a></div></div>`)}
function movement(){const max=Math.max(1,...state.movement.flatMap(m=>[m.borrowed,m.returned]));return state.stock.map(s=>{const m=state.movement.find(m=>m.tool===s.tool)||{borrowed:0,returned:0};return `<div class="movement"><div class="movement-head"><b>${s.tool}</b><span class="muted">${m.borrowed} 대여 / ${m.returned} 반납</span></div><div class="bar-track"><div class="bar" style="width:${m.borrowed/max*100}%"></div></div><div class="bar-track"><div class="bar return" style="width:${m.returned/max*100}%"></div></div></div>`}).join('')}
function holderSummary(){const loans=state.active_loans||[];const loanLines=loans.length?`<div class="active-loans">${loans.map(l=>`<div class="holder-line"><span><b>${esc(l.name)}</b>${l.plant?` · ${esc(l.plant)}`:''}<br><small class="muted">${l.rent_start&&l.rent_due?periodLabel(l.rent_start,l.rent_due):'기간 미지정'}${l.overdue?' · 미반납':''}</small></span><span>${Object.entries(l.items).map(([k,v])=>`${esc(k)} <b>${v}개</b>`).join(' · ')}</span></div>`).join('')}</div>`:'';return (state.holders.length?state.holders.map(h=>`<div class="holder-line"><span>${esc(h.name)}</span><span>${esc(h.tool)} <b>${h.qty}개</b></span></div>`).join(''):'<div class="empty">현재 대여 중인 공구가 없습니다.</div>')+(loanLines?`<div class="loan-subhead">대여 기간별</div>`+loanLines:'')}
function workerOverview(){const mine=state.stock.reduce((a,s)=>a+s.mine,0);const overdue=state.overdue||[];const loans=state.loans||[];const banner=overdue.length?`<div class="overdue-banner" role="alert"><div class="overdue-kicker">미반납 알림</div><div class="overdue-title">미반납</div><p>반납 예정일이 지나 하루가 지났습니다. 즉시 반납해 주세요.</p>${overdue.map(o=>`<div class="overdue-item"><b>${o.plant?esc(o.plant)+' · ':''}${periodLabel(o.rent_start,o.rent_due)}</b><span>${Object.entries(o.items).map(([k,v])=>`${esc(k)} ${v}개`).join(' · ')} · ${o.days_overdue}일 연체</span></div>`).join('')}</div>`:`<div class="overdue-example"><b>장기 대여 예시</b><span>${periodLabel('2026-11-09','2026-11-16')}</span><small>반납 예정일 다음 날부터 이 자리에 빨간 <b>미반납</b> 알림이 크게 표시됩니다.</small></div>`;const loanBox=loans.length?`<div class="loan-list">${loans.map(l=>`<article class="card loan-card ${l.overdue?'is-overdue':''}"><div><b>${l.rent_start&&l.rent_due?periodLabel(l.rent_start,l.rent_due):'대여 기간 미지정'}</b>${l.plant?`<span class="badge gray">${esc(l.plant)}</span>`:''}${l.overdue?'<span class="badge overdue-badge">미반납</span>':'<span class="badge green">대여 중</span>'}</div><p class="muted">${Object.entries(l.items).map(([k,v])=>`${esc(k)} ${v}개`).join(' · ')}</p></article>`).join('')}</div>`:'<div class="empty">진행 중인 장기 대여가 없습니다. 예약 후 당일 촬영·확정하세요.</div>';return heading('내 작업 공간','필요한 공구를 확인하고 대여·반납을 시작하세요.')+banner+`<section class="worker-hero"><div><span class="tag">MY WORKSPACE</span><h2>${esc(user.name)}님, 안녕하세요.</h2><p class="muted">현재 <b>${mine}개</b>의 공구를 대여하고 있습니다.</p></div><div class="worker-actions"><button class="primary" data-start="borrow">↗ 공구 대여</button><button data-start="return">↙ 공구 반납</button></div></section>`+panel('내 장기 대여','예약·승인 후 촬영으로 확정한 대여 기간입니다.',loanBox,'<a href="#reserve" data-nav="reserve">예약하기 →</a>')+`<h2>내 대여 현황</h2><p class="muted">현재 반납하지 않은 공구 수량입니다.</p><div class="personal-tools">${state.stock.map(s=>`<article class="card personal-tool"><span class="muted">${s.tool}</span><strong>${s.mine}<small> 개</small></strong><small class="muted">전체 대여 가능 ${s.available}개 · 예약 ${s.reserved||0}개</small></article>`).join('')}</div>`+panel('내 최근 출납 기록','내 계정으로 확정한 대여·반납 내역입니다.',recordsTable(state.groups.slice(0,5)),'<a href="#history" data-nav="history">전체 보기 →</a>')}
function stockView(){const pending=(state.damages||[]).filter(d=>d.status==='pending');const damageBox=pending.length?`<div class="scroll"><table><thead><tr><th>신고 시간</th><th>사용자</th><th>구분</th><th>공구</th><th>수량</th><th>메모</th><th>처리</th></tr></thead><tbody>${pending.map(d=>`<tr><td>${time(d.created)}</td><td><b>${esc(d.name)}</b></td><td><span class="badge ${d.issue==='수리 필요'?'amber':'overdue-badge'}">${esc(d.issue||'파손')}</span></td><td>${esc(d.tool)}</td><td><b>${d.qty}</b></td><td>${esc(d.note||'—')}</td><td class="reserve-actions"><button class="primary" data-damage-act="process" data-id="${d.id}">재고에서 제외</button>${d.issue==='수리 필요'?`<button data-damage-act="repair" data-id="${d.id}">수리 완료</button>`:''}<button class="quiet" data-damage-act="dismiss" data-id="${d.id}">정상으로 처리</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">대기 중인 파손·수리 신고가 없습니다.</div>';return heading('공구·재고 관리','전체 보유 수량을 조정하고 파손·수리 재고를 처리하세요.')+panel('파손·수리 신고 대기','파손은 재고 제외, 수리 필요는 수리 완료 시 가용 재고로 복귀합니다.',damageBox)+panel('등록 공구','대여 가능 = 전체 − 대여 중 − 예약 − 파손/수리 대기',toolsTable())+panel('보유 수량 조정','대여 중·파손/수리 대기 수량 미만으로 변경할 수 없습니다.',state.stock.map(s=>`<form class="editor" data-stock="${esc(s.tool)}"><div><b>${s.tool}</b><p class="muted">대여 중 ${s.borrowed} · 예약 ${s.reserved||0} · 이상 대기 ${s.damaged||0} · 대여 가능 ${s.available}</p></div><div><label for="qty-${s.tool}">전체 보유 수량</label><div class="stepper"><button type="button" data-delta="-1" aria-label="${s.tool} 감소">−</button><input id="qty-${s.tool}" name="total" type="number" min="0" max="100000" step="1" required value="${s.total}"><button type="button" data-delta="1" aria-label="${s.tool} 증가">+</button></div><div class="before-after">${s.total} → <span data-next>${s.total}</span>개</div></div><label>변경 이유<select name="reason"><option>신규 구매 및 추가</option><option>폐기</option><option>파손</option><option>재고 정정</option></select></label><div class="actions"><button type="reset">취소</button><button class="primary">저장</button></div></form>`).join(''))+panel('재고 변경 이력','관리자가 확정한 변경을 기록합니다.',state.adjustments.length?`<div class="scroll"><table><thead><tr><th>변경 시간</th><th>관리자</th><th>공구</th><th>변경 전 → 후</th><th>사유</th></tr></thead><tbody>${state.adjustments.map(a=>`<tr><td>${time(a.created)}</td><td>${esc(a.name)}</td><td>${esc(a.tool)}</td><td>${a.before_qty} → <b>${a.after_qty}</b></td><td>${esc(a.reason)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">재고 변경 이력이 없습니다.</div>')}

function historyView(){return heading(user.role==='admin'?'출납 이력':'내 출납 이력','처리별 공구 상세와 기록을 확인하세요.')+panel('출납 기록','최근 200건의 처리 · 시간은 한국 기준입니다.',`<div class="filterbar"><input id="history-search" aria-label="사용자 또는 공구 검색" placeholder="사용자 또는 공구 검색"><select id="history-kind" aria-label="출납 유형"><option value="">전체 유형</option><option value="borrow">대여</option><option value="return">반납</option></select>${user.role==='admin'?`<select id="history-user" aria-label="사용자 필터"><option value="">전체 사용자</option>${state.users.map(u=>`<option>${esc(u.name)}</option>`).join('')}</select>`:''}</div><div id="records">${recordsTable(state.groups)}</div>`)}
function usersView(){return heading('사용자별 출납 현황','각 사용자가 현재 보유한 공구와 처리 이력을 확인하세요.')+`<div class="holders">${state.users.map(u=>{const held=state.holders.filter(h=>h.name===u.name);return `<article class="card holder"><div class="holder-head"><div class="avatar">${esc(u.name[0])}</div><div><b>${esc(u.name)}</b><div class="muted">${u.role==='admin'?'관리자':'현장 작업자'}</div></div></div>${held.length?held.map(h=>`<div class="holder-line"><span>${esc(h.tool)}</span><b>${h.qty}개</b></div>`).join(''):'<p class="muted">현재 대여한 공구가 없습니다.</p>'}<button class="full" data-user-history="${esc(u.name)}">출납 이력 보기 →</button></article>`}).join('')}</div>`}
function photosView(){const shots=state.groups.filter(g=>g.has_photo);return heading(user.role==='admin'?'이벤트 사진':'내 이벤트 사진','출납 확정 시 저장된 촬영 사진을 확인합니다.')+panel('저장된 사진',shots.length?`사진 있는 처리 ${shots.length}건`:'아직 저장된 사진이 없습니다.',shots.length?`<div class="photo-grid">${shots.map(g=>`<article class="card photo-card" data-detail="${g.id}"><img src="/api/events/${g.id}/photo" alt="처리 #${g.id} 촬영 사진" loading="lazy"><div class="photo-meta"><b>#${g.id} · ${esc(g.name)}</b><span class="muted">${time(g.created)} · ${g.kind==='return'?'반납':'대여'}${g.plant?` · ${esc(g.plant)}`:''}</span>${g.rent_start&&g.rent_due?`<span class="muted">${periodLabel(g.rent_start,g.rent_due)}</span>`:''}<span>${g.items.map(i=>`${esc(i.tool)} ${i.qty}`).join(' · ')}</span></div></article>`).join('')}</div>`:'<div class="empty">촬영 후 출납을 확정하면 이곳에 표시됩니다.</div>')}

function reportView(){const rep=state.report;if(!rep)return heading('주간 운영 리포트','관리자 전용 운영 지표입니다.')+'<div class="empty">리포트를 불러오지 못했습니다.</div>';const tools=(rep.top_tools||[]),plants=(rep.by_plant||[]);return heading('주간 운영 리포트',`${rep.period_start} ~ ${rep.period_end} · 연체율·파손/수리율·인기 공구`)+`<div class="report-kpis"><article class="card report-kpi"><span>연체율</span><strong>${Math.round((rep.overdue_rate||0)*100)}%</strong><small>미반납 ${rep.overdue_open}/${rep.open_loans}건</small></article><article class="card report-kpi"><span>파손·수리율</span><strong>${Math.round((rep.damage_rate||0)*100)}%</strong><small>파손 ${rep.damaged_qty} · 수리 ${rep.repair_qty} / 반납 ${rep.return_qty}</small></article><article class="card report-kpi"><span>주간 대여</span><strong>${rep.borrow_qty}</strong><small>반납 ${rep.return_qty}개</small></article></div>`+panel('공구별 대여','최근 7일간 공구별 대여 수량',`<div class="panel-body">${tools.length?tools.map(t=>{const max=Math.max(1,...tools.map(x=>x.qty));return `<div class="movement"><div class="movement-head"><b>${esc(t.tool)}</b><span class="muted">${t.qty}개 대여</span></div><div class="bar-track"><div class="bar" style="width:${t.qty/max*100}%"></div></div></div>`}).join(''):'<div class="empty">이번 주 대여 기록이 없습니다.</div>'}</div>`)+panel('공정별 대여','최근 7일간 공정별 대여 수량',`<div class="panel-body">${plants.length?plants.map(t=>{const max=Math.max(1,...plants.map(x=>x.qty));return `<div class="movement"><div class="movement-head"><b>${esc(t.plant)}</b><span class="muted">${t.qty}개 대여</span></div><div class="bar-track"><div class="bar return" style="width:${t.qty/max*100}%"></div></div></div>`}).join(''):'<div class="empty">공정별 대여 기록이 없습니다.</div>'}</div>`)}

function reserveView(){const list=state.reservations||[];const mine=user.role!=='admin';const rowsHtml=list.length?`<div class="scroll"><table><thead><tr><th>상태</th><th>사용자</th><th>공정</th><th>대여 예정 기간</th><th>공구</th><th>처리</th></tr></thead><tbody>${list.map(r=>`<tr><td><span class="badge ${r.status==='approved'?'green':r.status==='pending'?'amber':r.status==='active'?'':'gray'}">${statusLabel[r.status]||r.status}</span></td><td><b>${esc(r.name)}</b></td><td>${esc(r.plant||'—')}</td><td>${periodLabel(r.rent_start,r.rent_due,r.rent_due_hour)}</td><td>${r.items.map(i=>`${esc(i.tool)} ${i.qty}`).join(' · ')}</td><td class="reserve-actions">${r.status==='pending'&&user.role==='admin'?`<button class="primary" data-reserve-act="approve" data-id="${r.id}">승인</button><button data-reserve-act="reject" data-id="${r.id}">거절</button>`:''}${['pending','approved'].includes(r.status)&& (mine||user.role==='admin')?`<button class="quiet" data-reserve-act="cancel" data-id="${r.id}">취소</button>`:''}${r.status==='approved'&&mine?`<button class="primary" data-fulfill="${r.id}">촬영·대여 →</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">아직 예약이 없습니다. 아래에서 장기 대여를 예약하세요.</div>';const form=mine||user.role==='admin'?`<form id="reserve-form" class="reserve-form"><p class="flow-note">작업자가 공구와 대여·반납 예정일을 예약하면 관리자 승인 후, 당일 촬영·확정으로 실제 대여가 됩니다. 재고는 대여 중과 별도로 예약 수량이 차감됩니다.</p><div class="period-box"><label>대여 시작일<input type="date" name="rent_start" required value="${todayISO()}"></label><span class="period-tilde">~</span><label>반납 예정일<input type="date" name="rent_due" required value="${todayISO()}"></label><label>반납 예정 시간<select name="rent_due_hour" required>${hourOptions('18')}</select></label></div><p class="muted period-example">선택한 반납 예정 시간이 지나면 미반납 알림이 표시됩니다.</p><label class="reserve-pick">사용 공정<select name="plant" required><option value="">공정 선택</option>${plantOptions()}</select></label><div class="reserve-tools">${state.stock.map(s=>`<label class="reserve-tool">${esc(s.tool)}<input type="number" name="qty-${esc(s.tool)}" min="0" max="100000" step="1" value="0"><small class="muted">가능 ${s.available} · 예약 ${s.reserved||0}</small></label>`).join('')}</div><p id="reserve-error" class="error" role="alert"></p><button class="primary" type="submit">장기 대여 예약 신청</button></form>`:'';return heading(user.role==='admin'?'장기 대여 예약':'내 장기 대여 예약','공구 + 대여일/반납 예정 시간을 예약하고, 승인 후 촬영으로 확정합니다.')+panel('예약 현황','승인 대기 · 승인됨 · 대여 중 상태를 확인합니다.',rowsHtml)+panel('새 예약','반납 예정 시간은 01시부터 24시까지 선택할 수 있습니다.',form)}

function steps(n){return `<div class="steps"><span class="${n===1?'active':''}">01 촬영</span><span>→</span><span class="${n===2?'active':''}">02 확인·수정</span><span>→</span><span class="${n===3?'active':''}">03 처리 완료</span></div>`}
function cameraView(){return `<div class="flow">${heading(`공구 ${kind==='borrow'?'대여':'반납'}`,'공구가 겹치지 않도록 놓고 전체가 보이게 촬영하세요.','<button data-nav="overview">← 돌아가기</button>')}${steps(1)}<section class="panel"><div class="panel-head"><div><h2>공구 촬영</h2><p class="muted">드라이버 · 몽키 스패너 · 펜치 · 망치</p></div><span class="badge">${kind==='borrow'?'대여':'반납'}</span></div><div class="panel-body"><div class="camera-frame"><span class="camera-tag">${photo?'촬영 이미지':'CAMERA PREVIEW'}</span>${photoURL?`<img src="${photoURL}" alt="촬영한 공구">`:'<video id="camera-video" autoplay playsinline muted></video><div id="camera-placeholder" class="camera-message">'+icon('camera')+'<div>카메라를 켜거나 촬영한 사진을 선택하세요.</div></div>'}</div><p id="camera-error" class="error" role="alert"></p><div class="camera-actions">${photo?'<button id="retake">재촬영</button><button class="primary" id="recognize">AI 인식하기 →</button>':'<button id="open-camera">카메라 켜기</button><button id="capture" class="primary" disabled>사진 촬영</button><button id="choose-file">사진 선택</button>'}<input id="image-file" type="file" accept="image/*" capture="environment" hidden></div><p class="muted" style="text-align:center;margin-top:16px">출납을 확정하면 촬영 사진이 해당 이벤트에 함께 저장됩니다.</p></div></section>${!config.ai_ready?'<div class="flow-note">공구 전용 AI 모델이 아직 연결되지 않았습니다. 임의의 인식 결과를 표시하지 않습니다. 촬영 후 수동 입력으로 출납할 수 있습니다.</div>':''}<button class="full" id="manual-review">수동 입력으로 계속 →</button></div>`}
function reviewView(){const preview=annotatedURL||photoURL;const approved=(state.reservations||[]).filter(r=>r.status==='approved');const damageHint=kind==='return'?'<div class="flow-note">반납 공구마다 정상·파손·수리 필요를 선택하세요. 파손은 재고 제외, 수리 필요는 수리 완료 후 복귀할 수 있습니다.</div>':'';const period=kind==='borrow'?`<div class="period-box review-period"><label>대여 시작일<input id="rent-start" type="date" required value="${rentStart||todayISO()}"></label><span class="period-tilde">~</span><label>반납 예정일<input id="rent-due" type="date" required value="${rentDue||todayISO()}"></label><label>반납 예정 시간<select id="rent-due-hour" required>${hourOptions(rentDueHour)}</select></label></div><p class="muted period-example">반납 예정 시간은 01시부터 24시까지 선택할 수 있습니다.</p><label class="reserve-pick">사용 공정<select id="plant-area" required><option value="">공정 선택</option>${plantOptions(plantArea)}</select></label>${approved.length?`<label class="reserve-pick">승인된 예약 선택(선택)<select id="reservation-pick"><option value="">직접 입력 · 예약 없음</option>${approved.map(r=>`<option value="${r.id}" ${selectedReservation===r.id?'selected':''}>#${r.id} ${periodLabel(r.rent_start,r.rent_due,r.rent_due_hour)} · ${r.items.map(i=>i.tool+' '+i.qty).join(', ')}</option>`).join('')}</select></label>`:''}`:'';return `<div class="flow">${heading('공구 확인·수정',`${kind==='borrow'?'대여':'반납'}할 공구 종류와 수량을 최종 확인하세요.`)}${steps(2)}<div class="flow-note">${source==='model'?'AI 인식 결과입니다. 실제 공구와 수량을 확인하고 필요한 내용을 수정하세요.':'수동 입력입니다. 실제 촬영 공구를 확인하여 종류와 수량을 입력하세요.'}</div>${damageHint}<section class="panel"><div class="panel-head"><h2>${kind==='borrow'?'대여':'반납'} 목록</h2><span class="badge gray">${esc(user.name)}</span></div><div class="panel-body"><div class="result-layout"><div>${preview?`<img class="result-image" src="${preview}" alt="${annotatedURL?'AI 감지 박스 표시 사진':'촬영한 공구'}">`:'<div class="empty card">첨부된 이미지 없음</div>'}<p class="result-meta">${annotatedURL?'색 박스는 AI가 감지한 공구입니다. 종류와 수량을 확인하고 수정하세요.':'각 항목의 종류와 수량을 수정할 수 있습니다.'}</p><button id="back-camera">← 재촬영</button></div><div>${period}<div id="result-rows"></div><button id="add-row" class="full">+ 공구 항목 추가</button><div id="result-summary" class="result-meta" style="margin-top:18px"></div></div></div><div class="actions" style="justify-content:flex-end;margin-top:28px"><button data-nav="overview">취소</button><button class="primary" id="confirm-event">${kind==='borrow'?'대여':'반납'} 내용 확인 →</button></div></div></section></div>`}

function completeView(){return `<div class="flow">${steps(3)}<section class="panel complete"><div class="complete-icon">✓</div><h1>공구 ${receipt.kind==='borrow'?'대여':'반납'} 완료</h1><p class="muted">출납 기록이 안전하게 저장되었습니다.${receipt.has_photo?' 촬영 사진도 함께 보관되었습니다.':' 촬영 사진이 없어 사진 없이 저장되었습니다.'}</p><div class="receipt"><p><span class="muted">처리 식별자</span><b>#${receipt.id}</b></p><p><span class="muted">사용자</span><b>${esc(receipt.name)}</b></p><p><span class="muted">처리 시간</span><b>${time(receipt.created)}</b></p>${Object.entries(receipt.items).map(([t,q])=>`<p><span>${esc(t)}</span><b>${q}개</b></p>`).join('')}${receipt.plant?`<p><span class="muted">사용 공정</span><b>${esc(receipt.plant)}</b></p>`:''}${receipt.rent_start&&receipt.rent_due?`<p><span class="muted">대여 예정일</span><b>${dayLabel(receipt.rent_start)} ~ ${dayLabel(receipt.rent_due)} ${hourLabel(receipt.rent_due_hour)}</b></p>`:''}${receipt.damage&&Object.keys(receipt.damage).length?`<p><span class="muted">이상 신고</span><b class="damage-text">${Object.entries(receipt.damage).map(([k,v])=>`${esc(k)} ${v}개${receipt.issues&&receipt.issues[k]?`(${esc(receipt.issues[k])})`:''}`).join(' · ')}</b></p>`:''}<p><span class="muted">기록 구분</span><b>${esc(modeLabel())}</b></p></div><button class="primary" data-nav="overview">메인 대시보드로 이동 →</button></section></div>`}
function render(){navigation();const content=$('#content');content.innerHTML=page==='overview'?(user.role==='admin'?adminOverview():workerOverview()):page==='stock'?stockView():page==='history'?historyView():page==='photos'?photosView():page==='reserve'?reserveView():page==='report'?reportView():page==='users'?usersView():page==='camera'?cameraView():page==='review'?reviewView():completeView();if(page==='review')renderRows();if(page==='overview'&&user.role==='admin'){const title=[...content.querySelectorAll('.panel h2')].find(x=>x.textContent==='주간 운영 리포트');title?.closest('.panel')?.remove()}if(page==='overview'&&user.role!=='admin')content.querySelector('.overdue-example')?.remove();if(page==='reserve'&&user.role==='admin'){content.querySelectorAll('.panel')[1]?.remove();content.querySelectorAll('[data-reserve-act="cancel"]').forEach(x=>x.remove());content.querySelectorAll('[data-reserve-act="approve"]').forEach(x=>x.textContent='가능');content.querySelectorAll('[data-reserve-act="reject"]').forEach(x=>x.textContent='불가')}}
function go(n){if(!user)return;if(['stock','users','report'].includes(n)&&user.role!=='admin')return notify('관리자만 접근할 수 있습니다.');stopCamera();page=n;render();window.scrollTo(0,0)}
function renderRows(){$('#result-rows').innerHTML=rows.map((r,i)=>{if(!r.condition)r.condition='ok';if(r.issueQty==null)r.issueQty=0;const dmg=kind==='return'?`<select data-row-condition="${i}" aria-label="공구 ${i+1} 상태"><option value="ok" ${r.condition==='ok'?'selected':''}>정상</option><option value="파손" ${r.condition==='파손'?'selected':''}>파손</option><option value="수리 필요" ${r.condition==='수리 필요'?'selected':''}>수리 필요</option></select><input type="number" min="0" max="${r.qty}" step="1" value="${r.condition==='ok'?0:(r.issueQty||r.qty)}" data-row-damage-qty="${i}" aria-label="공구 ${i+1} 이상 수량" ${r.condition==='ok'?'disabled':''} title="이상 수량">`:'';return `<div class="result-row"><select data-row-tool="${i}" aria-label="공구 ${i+1} 종류">${state.stock.map(s=>`<option ${s.tool===r.tool?'selected':''}>${s.tool}</option>`).join('')}</select><input type="number" min="1" max="100000" step="1" value="${r.qty}" data-row-qty="${i}" aria-label="공구 ${i+1} 수량">${dmg}<button data-remove-row="${i}" aria-label="공구 ${i+1} 제거">×</button></div>`}).join('');const note=kind==='return'?`<label class="damage-note">이상 메모(선택)<input id="damage-note" maxlength="200" placeholder="예: 파손-턱 휨 / 수리 필요-나사 헐거움" value="${esc(window._damageNote||'')}"></label>`:'';const compare=(kind==='return'&&(state.borrow_photos||[]).length)?`<div class="compare-box"><div class="compare-head"><b>대여 ↔ 반납 사진 비교</b><span class="muted">열린 대여 사진과 지금 촬영분을 나란히 확인하세요.</span></div><div class="compare-grid">${(state.borrow_photos||[]).slice(0,2).map(b=>`<figure><img src="/api/events/${b.id}/photo" alt="대여 #${b.id}"><figcaption>대여 #${b.id}<br>${periodLabel(b.rent_start,b.rent_due)}</figcaption></figure>`).join('')}<figure>${photoURL||annotatedURL?`<img src="${annotatedURL||photoURL}" alt="반납 촬영">`:'<div class="empty">반납 사진 없음</div>'}<figcaption>지금 반납 촬영</figcaption></figure></div></div>`:'';if(kind==='return'){const wrap=$('#result-summary');wrap.innerHTML=(rows.length?'공구마다 정상 / 파손 / 수리 필요를 선택하세요.':'인식된 공구가 없습니다. 항목을 추가하거나 재촬영하세요.')+note+compare}else{const a=$('#rent-start')?.value||rentStart,b=$('#rent-due')?.value||rentDue,pl=$('#plant-area')?.value||plantArea;const tip=rows.length?'최종 확정 시 최신 재고와 본인 대여 수량을 다시 확인합니다.':'인식된 공구가 없습니다. 항목을 추가하거나 재촬영하세요.';$('#result-summary').innerHTML=`${tip}${a&&b?`<div class="period-summary"><b>${periodLabel(a,b)}</b>${pl?` · 공정 ${esc(pl)}`:''}</div>`:''}`}}

const photoData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('반납 사진을 읽지 못했습니다. 다시 촬영하세요.'));reader.readAsDataURL(file)});
async function confirm(path,body,text){if(path==='events'&&body.kind==='return'){if(!photo)return notify('반납은 사진을 촬영하거나 선택해야만 가능합니다.');body.photo_data=await photoData(photo)}pending={path,body:{...body,mode:mode(),token:crypto.randomUUID()}};$('#confirm-text').textContent=`${modeLabel()} · ${user.name}\n\n${text}`;$('#confirm-error').textContent='';$('#confirm-dialog').showModal()}
async function cameraStart(){try{if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia)throw Error('카메라는 HTTPS 또는 이 컴퓨터의 localhost 접속에서 사용할 수 있습니다. 사진 선택을 이용하세요.');stopCamera();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(page!=='camera'){stopCamera();return}$('#camera-video').srcObject=stream;await $('#camera-video').play();$('#camera-placeholder').hidden=true;$('#capture').disabled=false;$('#camera-error').textContent=''}catch(e){stopCamera();const denied=e.name==='NotAllowedError';$('#camera-error').textContent=denied?'카메라 권한이 거부되었습니다. 브라우저에서 권한을 허용하고 다시 시도하거나 사진 선택을 이용하세요.':e.name==='NotFoundError'?'사용 가능한 카메라가 없습니다. 사진 선택을 이용하세요.':e.message||'카메라 실행 실패. 다시 시도하세요.'}}
function setPhoto(file){if(!file||!file.type.startsWith('image/'))return notify('이미지 파일을 선택하세요.');if(file.size>7*1024*1024)return notify('7MB 이하의 이미지를 선택하세요.');clearPhoto();photo=file;photoURL=URL.createObjectURL(file);render()}
async function recognize(){const b=$('#recognize');b.disabled=true;b.textContent='AI 인식 중…';try{const form=new FormData();form.append('image',photo,'capture.jpg');const result=await api('recognize',form,true);rows=Object.entries(result.items).map(([tool,qty])=>({tool,qty}));annotatedURL=result.annotated_image||null;source='model';go('review');if(!rows.length)notify('인식된 공구가 없습니다. 재촬영하거나 직접 추가하세요.')}catch(e){$('#camera-error').textContent=e.message;b.disabled=false;b.textContent='AI 인식 다시 시도'}}
function filterHistory(){const query=$('#history-search').value.trim().toLowerCase(),k=$('#history-kind').value,u=$('#history-user')?.value;$('#records').innerHTML=recordsTable(state.groups.filter(g=>(!k||g.kind===k)&&(!u||g.name===u)&&(!query||(g.name+' '+g.items.map(i=>i.tool).join(' ')+' '+(g.plant||'')+' '+(g.rent_start||'')+' '+(g.rent_due||'')).toLowerCase().includes(query))))}
function detail(id){const g=state.groups.find(g=>g.id===Number(id));if(!g)return;const compare=g.kind==='return'&&g.has_compare_photo?`<div class="compare-grid detail-compare"><figure><img src="/api/events/${g.compare_event_id}/photo" alt="대여 사진"><figcaption>대여 사진 #${g.compare_event_id}</figcaption></figure><figure>${g.has_photo?`<img src="/api/events/${g.id}/photo" alt="반납 사진">`:'<div class="empty">반납 사진 없음</div>'}<figcaption>반납 사진 #${g.id}</figcaption></figure></div>`:(g.has_photo?`<img class="detail-photo" src="/api/events/${g.id}/photo" alt="처리 #${g.id} 촬영 사진">`:'<p class="muted" style="margin-top:18px">저장된 촬영 사진이 없습니다.</p>');$('#detail-content').innerHTML=`<p class="muted">처리 #${g.id} · ${time(g.created)} · 완료</p><p><b>${esc(g.name)}</b> · ${g.kind==='borrow'?'대여':'반납'} · ${esc(modeLabel())}</p>${g.plant?`<p class="muted">사용 공정 · ${esc(g.plant)}</p>`:''}${g.rent_start&&g.rent_due?`<p class="muted">${periodLabel(g.rent_start,g.rent_due)}</p>`:''}${g.items.map(i=>`<div class="holder-line"><span>${esc(i.tool)}</span><b>${i.qty}개</b></div>`).join('')}${compare}<p class="muted" style="margin-top:18px">공구별 상세 ${g.items.length}개가 하나의 처리로 저장되었습니다.</p>`;$('#detail-dialog').showModal()}
function start(k){kind=k;clearPhoto();rows=[];source='manual';rentStart=todayISO();rentDue=todayISO();rentDueHour='18';plantArea=plantArea||((state.plants||[])[0]||'제선');selectedReservation=null;window._damageNote='';go('camera')}
document.addEventListener('click',e=>{if(kind==='return'&&!photo&&(e.target.closest('#manual-review')||e.target.closest('#confirm-event'))){e.preventDefault();e.stopImmediatePropagation();notify('반납은 사진을 촬영하거나 선택해야만 가능합니다.')}},true);
document.addEventListener('click',e=>{const ff=e.target.closest('[data-fulfill]');if(ff){const r=(state.reservations||[]).find(x=>x.id===Number(ff.dataset.fulfill));if(r)rentDueHour=String(r.rent_due_hour||24)}},true);
document.addEventListener('click',async e=>{const button=e.target.closest('[data-damage-act]');if(!button)return;e.preventDefault();const action=button.dataset.damageAct;button.disabled=true;try{await api(`damages/${button.dataset.id}/${action}`,{});await load();render();notify(action==='process'?'재고에서 제외했습니다.':action==='repair'?'수리 완료로 처리했습니다.':'정상으로 처리했습니다.')}catch(err){button.disabled=false;notify(err.message)}});
document.addEventListener('click',async e=>{const n=e.target.closest('[data-nav]');if(n){e.preventDefault();go(n.dataset.nav);return}const st=e.target.closest('[data-start]');if(st)return start(st.dataset.start);const de=e.target.closest('[data-detail]');if(de)return detail(de.dataset.detail);const uh=e.target.closest('[data-user-history]');if(uh){go('history');$('#history-user').value=uh.dataset.userHistory;filterHistory();return}const delta=e.target.closest('[data-delta]');if(delta){const f=delta.closest('form'),i=f.elements.total;i.value=Math.max(0,Math.min(100000,Number(i.value)+Number(delta.dataset.delta)));f.querySelector('[data-next]').textContent=i.value;return}const remove=e.target.closest('[data-remove-row]');if(remove){rows.splice(Number(remove.dataset.removeRow),1);renderRows();return}if(e.target.closest('[data-refresh]')){try{await load();render();notify('현황을 갱신했습니다.')}catch(e){notify(e.message)}return}const id=e.target.closest('button')?.id;if(id==='open-camera')await cameraStart();if(id==='capture'){try{const v=$('#camera-video');if(!v.videoWidth)throw Error('카메라가 준비되지 않았습니다.');const c=document.createElement('canvas');c.width=Math.min(v.videoWidth,1600);c.height=v.videoHeight*(c.width/v.videoWidth);c.getContext('2d').drawImage(v,0,0,c.width,c.height);c.toBlob(b=>b?setPhoto(b):notify('촬영에 실패했습니다. 다시 시도하세요.'),'image/jpeg',.9)}catch(e){notify(e.message)}}if(id==='choose-file')$('#image-file').click();if(id==='retake'){clearPhoto();render();await cameraStart()}if(id==='recognize')await recognize();if(id==='manual-review'){source='manual';rows=[];go('review')}if(id==='back-camera')go('camera');if(id==='add-row'){rows.push({tool:state.stock[0].tool,qty:1});renderRows()}if(id==='confirm-event'){try{const items={};for(const r of rows){if(!Number.isInteger(r.qty)||r.qty<1||r.qty>100000)throw Error('수량은 1 이상 100000 이하의 정수로 입력하세요.');items[r.tool]=(items[r.tool]||0)+r.qty}if(!rows.length)throw Error('공구 항목을 추가하세요.');const body={kind,items};let periodText='';if(kind==='return'){const damage={},issues={};for(const r of rows){if(r.condition==='ok')continue;const d=Number(r.issueQty||r.qty)||0;if(!Number.isInteger(d)||d<1||d>r.qty)throw Error('파손/수리 수량을 확인하세요.');damage[r.tool]=(damage[r.tool]||0)+d;issues[r.tool]=r.condition};body.damage=damage;body.issues=issues;body.damage_note=$('#damage-note')?.value||'';if(Object.keys(damage).length)periodText='\n이상 신고: '+Object.entries(damage).map(([t,q])=>`${t} ${q}개(${issues[t]})`).join(', ')}if(kind==='borrow'){rentStart=$('#rent-start')?.value||rentStart;rentDue=$('#rent-due')?.value||rentDue;if(!rentStart||!rentDue)throw Error('대여 시작일과 반납 예정일을 입력하세요.');if(rentDue<rentStart)throw Error('반납 예정일은 대여 시작일 이후여야 합니다.');body.rent_start=rentStart;body.rent_due=rentDue;plantArea=$('#plant-area')?.value||plantArea;if(!plantArea)throw Error('사용 공정을 선택하세요.');body.plant=plantArea;const pick=$('#reservation-pick')?.value;selectedReservation=pick?Number(pick):null;if(selectedReservation)body.reservation_id=selectedReservation;periodText='\n'+periodLabel(rentStart,rentDue)+'\n사용 공정: '+plantArea}for(const [tool,qty]of Object.entries(items)){const s=state.stock.find(s=>s.tool===tool);let limit=kind==='borrow'?s.available:s.mine;if(kind==='borrow'&&selectedReservation){const r=(state.reservations||[]).find(x=>x.id===selectedReservation);const hold=r?.items?.find(i=>i.tool===tool)?.qty||0;limit=s.available+hold}if(qty>limit)throw Error(`${tool}: ${kind==='borrow'?'대여 가능':'본인 대여'} 수량을 초과했습니다. 새로고침 후 확인하세요.`)}confirm('events',body,`${kind==='borrow'?'대여':'반납'}${periodText}\n`+Object.entries(items).map(([t,q])=>`${t} ${q}개`).join('\n'))}catch(e){notify(e.message)}}const ra=e.target.closest('[data-reserve-act]');if(ra){try{await api('reservations/'+ra.dataset.id+'/'+ra.dataset.reserveAct,{});await load();render();notify(ra.dataset.reserveAct==='approve'?'예약을 승인했습니다.':ra.dataset.reserveAct==='reject'?'예약을 거절했습니다.':'예약을 취소했습니다.')}catch(err){notify(err.message)}return}const ff=e.target.closest('[data-fulfill]');if(ff){const r=(state.reservations||[]).find(x=>x.id===Number(ff.dataset.fulfill));if(!r)return;kind='borrow';selectedReservation=r.id;rentStart=r.rent_start;rentDue=r.rent_due;plantArea=r.plant||'';rows=r.items.map(i=>({tool:i.tool,qty:i.qty}));clearPhoto();source='manual';go('camera');notify('승인된 예약으로 촬영·대여를 진행하세요.');return}});
document.addEventListener('input',e=>{if(e.target.matches('[data-row-qty]')){const i=Number(e.target.dataset.rowQty);rows[i].qty=Number(e.target.value);if(rows[i].issueQty>rows[i].qty)rows[i].issueQty=rows[i].qty;const dq=document.querySelector(`[data-row-damage-qty="${i}"]`);if(dq){dq.max=rows[i].qty;if(Number(dq.value)>rows[i].qty)dq.value=rows[i].qty}}if(e.target.matches('[data-row-damage-qty]')){const i=Number(e.target.dataset.rowDamageQty);rows[i].issueQty=Math.max(0,Math.min(rows[i].qty,Number(e.target.value)||0));if(rows[i].issueQty>0&&rows[i].condition==='ok')rows[i].condition='파손'}if(e.target.id==='damage-note')window._damageNote=e.target.value;if(e.target.closest('[data-stock]')&&e.target.name==='total')e.target.closest('form').querySelector('[data-next]').textContent=e.target.value;if(e.target.id==='history-search')filterHistory()});
document.addEventListener('change',e=>{if(e.target.id==='rent-due-hour'){rentDueHour=e.target.value;if(page==='review')renderRows()}if(e.target.id==='reservation-pick'){const r=(state.reservations||[]).find(x=>x.id===Number(e.target.value));if(r)rentDueHour=String(r.rent_due_hour||24)}},true);
document.addEventListener('change',e=>{if(e.target.matches('[data-row-tool]'))rows[Number(e.target.dataset.rowTool)].tool=e.target.value;if(e.target.matches('[data-row-condition]')){const i=Number(e.target.dataset.rowCondition);rows[i].condition=e.target.value;if(rows[i].condition==='ok')rows[i].issueQty=0;else if(!rows[i].issueQty)rows[i].issueQty=rows[i].qty;const dq=document.querySelector(`[data-row-damage-qty="${i}"]`);if(dq){dq.disabled=rows[i].condition==='ok';dq.value=rows[i].issueQty}};if(e.target.id==='image-file')setPhoto(e.target.files[0]);if(['history-kind','history-user'].includes(e.target.id))filterHistory();if(e.target.id==='rent-start'||e.target.id==='rent-due'||e.target.id==='plant-area'){rentStart=$('#rent-start')?.value||rentStart;rentDue=$('#rent-due')?.value||rentDue;plantArea=$('#plant-area')?.value||plantArea;if(page==='review')renderRows()}if(e.target.id==='reservation-pick'){const r=(state.reservations||[]).find(x=>x.id===Number(e.target.value));selectedReservation=r?r.id:null;if(r){rentStart=r.rent_start;rentDue=r.rent_due;plantArea=r.plant||plantArea;rows=r.items.map(i=>({tool:i.tool,qty:i.qty}));const a=$('#rent-start'),b=$('#rent-due'),pl=$('#plant-area');if(a)a.value=rentStart;if(b)b.value=rentDue;if(pl&&plantArea)pl.value=plantArea;renderRows()}else selectedReservation=null}});
document.addEventListener('reset',e=>{if(e.target.matches('[data-stock]'))setTimeout(()=>e.target.querySelector('[data-next]').textContent=e.target.elements.total.value,0)});
document.addEventListener('submit',async e=>{if(e.target.id==='reserve-form'){e.preventDefault();const f=e.target,err=$('#reserve-error');err.textContent='';try{const items={};for(const s of state.stock){const q=Number(f.elements['qty-'+s.tool].value||0);if(q){if(!Number.isInteger(q)||q<1)throw Error('수량은 1 이상 정수로 입력하세요.');items[s.tool]=q}}if(!Object.keys(items).length)throw Error('예약할 공구 수량을 입력하세요.');const rent_start=f.rent_start.value,rent_due=f.rent_due.value;if(!rent_start||!rent_due)throw Error('대여 시작일과 반납 예정일을 입력하세요.');if(rent_due<rent_start)throw Error('반납 예정일은 대여 시작일 이후여야 합니다.');const plant=f.plant.value;if(!plant)throw Error('사용 공정을 선택하세요.');await api('reservations',{mode:mode(),items,rent_start,rent_due,plant,token:crypto.randomUUID()});await load();render();notify('장기 대여 예약을 신청했습니다. 관리자 승인 후 촬영·대여하세요.')}catch(ex){err.textContent=ex.message;notify(ex.message)}return}if(!e.target.matches('[data-stock]'))return;e.preventDefault();const f=e.target,s=state.stock.find(s=>s.tool===f.dataset.stock),total=Number(f.elements.total.value);if(!Number.isInteger(total)||total<0)return notify('0 이상의 정수를 입력하세요.');confirm('stock',{tool:s.tool,total,version:s.version,reason:f.elements.reason.value},`${s.tool}\n보유 수량: ${s.total} → ${total}개\n변경 이유: ${f.elements.reason.value}`)});
$('#login-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter||e.target.querySelector('[type=submit]');if(btn)btn.disabled=true;$('#login-error').textContent='';try{const d=await api('login',Object.fromEntries(new FormData(e.target)));setUser(d);e.target.reset();await load();history.replaceState(null,'',d.role==='admin'?'/admin':'/dashboard');render()}catch(err){$('#login-error').textContent=err.message;notify(err.message)}finally{if(btn)btn.disabled=false}};
$('#logout').onclick=async()=>{try{await api('logout',{});loginView();history.replaceState(null,'','/')}catch(e){notify(e.message)}};
$('#mode').onchange=async()=>{stopCamera();clearPhoto();page='overview';$('#content').innerHTML='<div class="empty">현황을 불러오는 중…</div>';try{await load();render()}catch(e){notify(e.message)}};
$('#cancel-confirm').onclick=()=>{if(!saving){pending=null;$('#confirm-dialog').close()}};
$('#confirm-dialog').addEventListener('cancel',e=>{if(saving)e.preventDefault();else pending=null});
$('#save-confirm').onclick=async()=>{if(!pending||saving)return;saving=true;$('#save-confirm').disabled=true;$('#cancel-confirm').disabled=true;try{const result=await api(pending.path,pending.body),isEvent=pending.path==='events';pending=null;$('#confirm-dialog').close();if(isEvent){if(photo){try{const form=new FormData();form.append('image',photo,'capture.jpg');await api('events/'+result.id+'/photo',form,true);result.has_photo=true}catch(e){notify('출납은 저장됐지만 사진 저장에 실패했습니다: '+e.message)}}clearPhoto();receipt=result;page='complete';render();try{await load()}catch{notify('저장 완료. 현황 조회는 다시 시도하세요.')}}else{await load();render();notify('재고 변경이 저장되었습니다.')}}catch(e){$('#confirm-error').textContent=e.message}finally{saving=false;$('#save-confirm').disabled=false;$('#cancel-confirm').disabled=false}};
$('#close-detail').onclick=()=>$('#detail-dialog').close();
function theme(value){document.documentElement.dataset.theme=value;localStorage.setItem('stbm-theme',value);document.querySelectorAll('.theme-toggle').forEach(b=>{const dark=value==='dark';b.innerHTML=dark?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 13.2A9 9 0 0 1 10.8 3.1 9 9 0 1 0 20.8 13.2Z"/></svg>';b.setAttribute('aria-label',dark?'라이트 모드로 전환':'다크 모드로 전환');b.title=dark?'라이트 모드로 전환':'다크 모드로 전환'})}
theme(localStorage.getItem('stbm-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));document.querySelectorAll('.theme-toggle').forEach(b=>b.onclick=()=>theme(document.documentElement.dataset.theme==='dark'?'light':'dark'));
window.addEventListener('beforeunload',stopCamera);
(async()=>{try{setUser(await api('me'));await load();render()}catch(e){if(user)notify(e.message)}})();

function formatOverdueBanner(){
 const banner=$('.overdue-banner');if(!banner||!state)return;
 const message=banner.querySelector('p');if(message)message.textContent='반납 예정일이 지났습니다. 즉시 반납해 주세요.';
 const overdue=state.overdue||[];
 banner.querySelectorAll('.overdue-item').forEach((el,i)=>{
  if(el.dataset.formatted)return;
  const o=overdue[i];if(!o)return;
  const who=o.name||user?.name||'작업자',where=o.plant||'공정 미지정';
  el.innerHTML=`<b>${esc(who)} · ${esc(where)}</b><span>대여일 : ${dayLabel(o.rent_start)} ~ ${dayLabel(o.rent_due)} ${hourLabel(o.rent_due_hour)}</span><span>${Object.entries(o.items).map(([k,v])=>`${esc(k)} ${v}개`).join(' · ')} · ${o.days_overdue}일 연체</span>`;
  el.dataset.formatted='true';
 });
}
const overdueObserver=new MutationObserver(formatOverdueBanner);
overdueObserver.observe($('#content'),{childList:true,subtree:true});
formatOverdueBanner();

// Fixed worksite context; clock follows Korea time, independent of device timezone.
function updateSiteClock(){const now=new Date();$('#site-date').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(now);$('#site-time').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(now);$('#site-time').dateTime=now.toISOString()}
function weatherLabel(code){if(code===0)return '맑음';if([1,2].includes(code))return '구름 조금';if(code===3)return '흐림';if([45,48].includes(code))return '안개';if([51,53,55,56,57].includes(code))return '이슬비';if([61,63,65,66,67,80,81,82].includes(code))return '비';if([71,73,75,77,85,86].includes(code))return '눈';if([95,96,99].includes(code))return '뇌우';return '날씨 정보'}
async function updateSiteWeather(){const el=$('#site-weather');try{const response=await fetch('https://api.open-meteo.com/v1/forecast?latitude=35.99&longitude=129.36&current=temperature_2m,weather_code&timezone=Asia%2FSeoul',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('weather');const data=await response.json(),c=data.current;if(!Number.isFinite(c?.temperature_2m)||!Number.isInteger(c?.weather_code))throw Error('invalid');el.textContent=`${c.temperature_2m.toFixed(1)}°C · ${weatherLabel(c.weather_code)}`;el.title=`날씨 제공: Open-Meteo · 남구 대표 좌표 기준 · 기준 시각 ${c.time.replace('T',' ')} (한국 시간)`}catch{el.textContent='날씨 조회 불가';el.title='날씨 제공: Open-Meteo · 연결을 확인하세요. 10분마다 다시 조회합니다.'}}
updateSiteClock();setInterval(updateSiteClock,1000);updateSiteWeather();setInterval(updateSiteWeather,600000);
